package com.backend.nutri_predic.datasetmodelov6.service;
import com.backend.nutri_predic.cliente.repository.ClienteRepository; import com.backend.nutri_predic.datasetmodelov6.dto.*; import com.backend.nutri_predic.variablemodelov6.schema.FeatureSchemaV6Mapper; import java.time.LocalDate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PendientesEntrenamientoV6Service {private final ClienteRepository clientes;private final EstadoPreparacionClienteV6Service estado;private final DatasetModeloV6Service dataset;public PendientesEntrenamientoV6Service(ClienteRepository c,EstadoPreparacionClienteV6Service e,DatasetModeloV6Service d){clientes=c;estado=e;dataset=d;}@Transactional(readOnly=true)public PendientesEntrenamientoV6Response listar(LocalDate corte){var todos=clientes.findAll().stream().map(c->estado.estado(c.getId(),corte)).filter(x->!x.smokeTecnico()).toList();return new PendientesEntrenamientoV6Response(corte,FeatureSchemaV6Mapper.FEATURE_NAMES.size(),dataset.filas().size(),todos.stream().filter(x->!x.aptoParaEntrenamiento()).toList());}}
